def check_partial(labels, assigned):
    """Check if partial assignment is consistent"""
    used_labels = set()
    for i in assigned:
        if labels[i] in used_labels:
            return False
        used_labels.add(labels[i])

    used_diffs = set()
    for u, v in edges:
        if u in assigned and v in assigned:
            d = abs(labels[u] - labels[v])
            if d == 0 or d in used_diffs:
                return False
            used_diffs.add(d)
    return True

def solve():
    # Order: x2=15, x4=0 fixed
    # Then x6, x3, x9, x7, x10 from analysis
    # Then remaining: x0, x1, x5, x8, x11

    labels = [None] * 12
    labels[2] = 15
    labels[4] = 0

