                        labels[10] = x10

                        # Check consistency so far
                        assigned = {2, 4, 6, 3, 9, 7, 10}
                        if not check_partial(labels, assigned):
                            continue

                        # Now fill remaining: 0, 1, 5, 8, 11
                        used = {labels[i] for i in assigned}
                        remaining_labels = [v for v in range(22) if v not in used]

                        # Try all permutations of remaining 5 labels for positions 0,1,5,8,11
                        from itertools import permutations
                        for perm in permutations(remaining_labels, 5):
